import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.4s5LDCII.js";const p=JSON.parse('{"title":"成人高尿酸血症与痛风食养指南（2024年版）","description":"国家卫健委《成人高尿酸血症与痛风食养指南（2024年版）》要点导读：低嘌呤膳食、足量饮水、控制体重。","frontmatter":{"title":"成人高尿酸血症与痛风食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845129551_37712.pdf","status":"现行","tags":["痛风","高尿酸","食养","饮食指导"],"reviewed":false,"description":"国家卫健委《成人高尿酸血症与痛风食养指南（2024年版）》要点导读：低嘌呤膳食、足量饮水、控制体重。"},"headers":[],"relativePath":"guides/gout-2024.md","filePath":"guides/gout-2024.md"}'),d={name:"guides/gout-2024.md"};function s(i,t,l,n,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="成人高尿酸血症与痛风食养指南-2024年版" tabindex="-1">成人高尿酸血症与痛风食养指南（2024年版） <a class="header-anchor" href="#成人高尿酸血症与痛风食养指南-2024年版" aria-label="Permalink to &quot;成人高尿酸血症与痛风食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845129551_37712.pdf" target="_blank" rel="noreferrer">指南全文 PDF</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人高尿酸血症与痛风患者，以及尿酸偏高、有痛风家族史的人群及其家人。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>减少高嘌呤膳食摄入</strong>：合理搭配膳食，少吃动物内脏、部分海鲜、浓肉汤等高嘌呤食物。</li><li><strong>足量饮水</strong>：在心、肾功能正常的前提下，每天饮水 2000～3000mL（详见原文）。</li><li><strong>控制体重</strong>：肥胖是高尿酸血症与痛风发生的独立危险因素。</li><li><strong>限制酒精与含果糖饮料</strong>：急性发作期与缓解期的膳食要求不同，详见原文。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>指南按<strong>不同地区、不同季节</strong>给出食谱示例，并按中医辨证给出食药物质与食养方建议；具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月（具体日期待核对原文）</td></tr></tbody></table>',11)])])}const g=a(d,[["render",s]]);export{p as __pageData,g as default};
